1	import React, { useState, useEffect, useCallback } from 'react';
2	import { useSearchParams } from 'react-router-dom';
3	import {
4	  getCozinhaToken, setCozinhaToken, clearCozinhaToken,
5	  getKdsItens, marcarItemPronto, reimprimirItem, iniciarPreparoItem,
6	} from '../../services/cozinhaPortalService';
7	import { printTicketSetor } from '../../utils/printComanda';
8	import Icon from '../../components/AppIcon';
9	
10	const KdsLogin = ({ onLogin }) => {
11	  const [token, setToken] = useState('');
12	  const [erro, setErro] = useState(null);
13	  const [loading, setLoading] = useState(false);
14	
15	  const handleSubmit = async (e) => {
16	    e.preventDefault();
17	    setErro(null);
18	    setLoading(true);
19	    setCozinhaToken(token.trim());
20	    try {
21	      onLogin();
22	    } finally {
23	      setLoading(false);
24	    }
25	  };
26	
27	  return (
28	    <div className="min-h-screen bg-[#1A1A1A] flex items-center justify-center p-4">
29	      <div className="bg-[#232323] rounded-2xl border border-[#2A2A2A] p-6 w-full max-w-sm shadow-2xl">
30	        <div className="text-center mb-6">
31	          <div className="w-14 h-14 bg-orange-500/10 rounded-2xl flex items-center justify-center mx-auto mb-3">
32	            <Icon name="Printer" size={28} className="text-orange-400" />
33	          </div>
34	          <h1 className="text-lg font-black text-white">Tela de Setor (KDS)</h1>
35	          <p className="text-sm text-[#71717A] dark:text-[#A1A1AA] mt-1">Cole o token de cozinha recebido do restaurante</p>
36	        </div>
37	        <form onSubmit={handleSubmit} className="space-y-3">
38	          <input value={token} onChange={(e) => setToken(e.target.value)} placeholder="Token de acesso..." required
39	            className="w-full bg-[#1A1A1A] border border-[#3A3A3A] rounded-xl px-3 py-3 text-sm font-mono text-white focus:outline-none focus:border-orange-500" />
40	          {erro && <p className="text-xs text-red-400">{erro}</p>}
41	          <button type="submit" disabled={loading || !token.trim()}
42	            className="w-full py-3 bg-orange-500 text-white font-bold rounded-xl hover:bg-orange-600 disabled:opacity-50 text-sm">
43	            Entrar
44	          </button>
45	        </form>
46	      </div>
47	    </div>
48	  );
49	};
50	
51	const RestauranteKdsSetor = () => {
52	  const [searchParams] = useSearchParams();
53	  const impressoraId = searchParams.get('impressora_id');
54	  const setorNome = searchParams.get('setor') ?? 'Setor';
55	
56	  const [authed, setAuthed] = useState(() => {
57	    const urlToken = searchParams.get('cozinha_token');
58	    if (urlToken) setCozinhaToken(urlToken);
59	    return !!getCozinhaToken();
60	  });
61	  const [itens, setItens] = useState([]);
62	  const [erro, setErro] = useState(null);
63	
64	  const carregar = useCallback(async () => {
65	    if (!impressoraId) return;
66	    try {
67	      const { itens } = await getKdsItens(impressoraId);
68	      setItens(itens);
69	      setErro(null);
70	    } catch (err) {
71	      if (!getCozinhaToken()) setAuthed(false);
72	      setErro(err.message);
73	    }
74	  }, [impressoraId]);
75	
76	  useEffect(() => {
77	    if (!authed) return;
78	    carregar();
79	    const interval = setInterval(carregar, 15000);
80	    return () => clearInterval(interval);
81	  }, [authed, carregar]);
82	
83	  if (!authed) return <KdsLogin onLogin={() => setAuthed(true)} />;
84	  if (!impressoraId) {
85	    return <div className="min-h-screen bg-[#1A1A1A] text-white p-6">Adicione ?impressora_id=ID na URL.</div>;
86	  }
87	
88	  const marcarPronto = async (itemId) => {
89	    await marcarItemPronto(itemId);
90	    carregar();
91	  };
92	
93	  const iniciarPreparo = async (item) => {
94	    await iniciarPreparoItem(item.id);
95	    carregar();
96	  };
97	
98	  const reimprimir = async (item) => {
99	    try {
100	      const res = await reimprimirItem(item.id);
101	      if (res.via === 'navegador') {
102	        printTicketSetor([item], { mesaLabel: item.mesa, cliente_mesa_nome: item.cliente }, setorNome);
103	      }
104	    } catch (err) {
105	      setErro(err.message);
106	    }
107	  };
108	
109	  return (
110	    <div className="min-h-screen bg-[#1A1A1A] p-4">
111	      <div className="flex items-center justify-between mb-4">
112	        <h1 className="text-xl font-black text-white uppercase">{setorNome}</h1>
113	        <button onClick={() => { clearCozinhaToken(); setAuthed(false); }} className="text-xs text-[#71717A] dark:text-[#A1A1AA]">Sair</button>
114	      </div>
115	      {erro && <p className="text-sm text-red-400 mb-3">{erro}</p>}
116	      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
117	        {itens.map((item, idx) => (
118	          <div key={item.id} className={`bg-[#232323] border rounded-2xl p-4 ${item.garcom_nao_entregou ? 'border-red-500 ring-1 ring-red-500/40' : idx === 0 ? 'border-yellow-400 dark:border-yellow-800/70 ring-1 ring-yellow-400/30' : 'border-[#2A2A2A]'}`}>
119	            <div className="flex items-center justify-between mb-1">
120	              <div className="flex items-center gap-2">
121	                <span className={`w-6 h-6 flex-shrink-0 rounded-lg flex items-center justify-center text-xs font-black ${idx === 0 ? 'bg-yellow-400 text-black' : 'bg-[#2A2A2A] text-white'}`}>
122	                  {idx + 1}
123	                </span>
124	                <span className="text-sm font-bold text-white">{item.quantity}x {item.product_name}</span>
125	              </div>
126	              <button onClick={() => reimprimir(item)}
127	                className="text-[10px] font-bold text-orange-400 border border-orange-500/40 rounded-lg px-2 py-1 hover:bg-orange-500/10 flex items-center gap-1 flex-shrink-0">
128	                <Icon name="Printer" size={11} /> Reimpressão
129	              </button>
130	            </div>
131	            {idx === 0 && <p className="text-[10px] font-bold text-yellow-400 uppercase tracking-wide mb-1">Próximo da fila</p>}
132	            {item.garcom_nao_entregou && (
133	              <p className="text-sm font-bold text-white bg-red-600 rounded px-1.5 py-0.5 mb-1 animate-pulse">
134	                Esse pedido não foi entregue — garçom não entregou
135	              </p>
136	            )}
137	            {item.is_auto_atendimento && (
138	              <p className="text-sm font-bold text-white bg-pink-600 rounded px-1.5 py-0.5 mb-1">
139	                Auto Atendimento — Mesa {item.mesa_numero ?? '?'}
140	              </p>
141	            )}
142	            {item.garcom_indo_buscar && (
143	              <p className={`text-sm font-bold text-white rounded px-1.5 py-0.5 mb-1 ${item.entregue_garcom ? 'bg-emerald-600' : 'bg-blue-600'}`}>
144	                {item.entregue_garcom ? 'Já entregue pelo garçom' : 'Garçom vindo buscar'}
145	              </p>
146	            )}
147	            <div className="flex items-center gap-2 text-xs text-[#71717A] dark:text-[#A1A1AA] mb-3">
148	              <Icon name="MapPin" size={12} />
149	              <span>{item.mesa && item.cliente ? `${item.mesa} • ${item.cliente}` : item.mesa ?? item.cliente ?? 'Avulsa'}</span>
150	              {item.garcom && (
151	                <>
152	                  <span className="text-[#3A3A3A]">•</span>
153	                  <Icon name="User" size={12} />
154	                  <span>{item.garcom}</span>
155	                </>
156	              )}
157	            </div>
158	            {item.status === 'enviado' ? (
159	              <button onClick={() => iniciarPreparo(item)}
