    setErroImport('O JSON precisa ser uma lista com pelo menos um produto.');
    return;
  }
  setImportando(true);
  try {
    const resultado = await importarProdutos(lista);
    setResultadoImport(resultado);
  } catch (err) {
    setErroImport(err.message);
  } finally {
    setImportando(false);
  }
};

